/* ================= v1.4: 70 SKINS NOVAS EM CATEGORIAS =================
   Cachorrinhos, Festas do Ano (por temporada), Comidinhas, Elementos, Oceano, Espaço e Arcade.
   Todas "divididas": base (parada, fica pronta em imagem) + fx (só o que mexe) — leves no celular. */
function* at(x,w,i,P,min=0,sh=37){for(let o=(i*sh)%P,X=Math.floor((x-o)/P)*P+o+P/2;X<x+w+30;X+=P){const a=hash(X*.13+i*3.7);if(a>=min)yield [X,a]}}
const blink=(seed,per=3300)=>((tNow+seed*997)%per)<140;
function mk(id,cat,cur,price,base,fx,extra){SKINS.push(Object.assign(fx?{id,cat,cur,price,base,fx,draw(c,x,y,w,i){this.base(c,x,y,w,i);this.fx(c,x,y,w,i)}}:{id,cat,cur,price,draw:base},extra||{}))}
const al=a=>WA[Math.max(0,Math.min(20,Math.round(a*20)))];
function star5(c,x,y,r,col){c.fillStyle=col;c.beginPath();for(let k=0;k<10;k++){const rr2=k%2?r*.45:r,a=-Math.PI/2+k*Math.PI/5;c.lineTo(x+Math.cos(a)*rr2,y+Math.sin(a)*rr2)}c.closePath();c.fill()}
function heart(c,x,y,s,col){c.fillStyle=col;c.beginPath();c.moveTo(x,y+s*.35);c.bezierCurveTo(x-s*.9,y-s*.35,x-s*.35,y-s*.95,x,y-s*.35);c.bezierCurveTo(x+s*.35,y-s*.95,x+s*.9,y-s*.35,x,y+s*.35);c.fill()}
function circ(c,x,y,r,col){c.fillStyle=col;c.beginPath();c.arc(x,y,r,0,TAU);c.fill()}
function ell(c,x,y,rx,ry,col,rot=0){c.fillStyle=col;c.beginPath();c.ellipse(x,y,rx,ry,rot,0,TAU);c.fill()}
function pxs(c,x,y,s,rows,cols){rows.forEach((r,j)=>[...r].forEach((ch,k)=>{if(ch!=='.'){c.fillStyle=cols[ch];c.fillRect(x+k*s,y+j*s,s,s)}}))}

/* ---------- carinha de cachorro ---------- */
function dogFace(c,cx,cy,r,o){
  if(o.ear==='point'){c.fillStyle=o.earC||o.fur;for(const s of [-1,1]){c.beginPath();c.moveTo(cx+s*r*.95,cy-r*.1);c.lineTo(cx+s*r*.7,cy-r*1.45);c.lineTo(cx+s*r*.15,cy-r*.8);c.closePath();c.fill()}}
  ell(c,cx,cy,r,r*.88,o.fur);
  if(o.spot)ell(c,cx+r*.45,cy-r*.35,r*.35,r*.3,o.spot);
  if(o.mask)ell(c,cx,cy+r*.12,r*.72,r*.6,o.mask);
  if(o.ear!=='point'){c.fillStyle=o.earC||o.fur;for(const s of [-1,1]){c.beginPath();c.ellipse(cx+s*r*.95,cy-r*.05,r*.32,r*.62,s*.35,0,TAU);c.fill()}}
  ell(c,cx,cy+r*.36,r*.5,r*.36,o.muzzle||'#fff3e0');
  const ey=cy-r*.12,ex=r*.4;for(const s of [-1,1]){ell(c,cx+s*ex,ey,r*.14,r*.17,o.eye||'#2a1a14');circ(c,cx+s*ex+r*.05,ey-r*.06,r*.05,'rgba(255,255,255,.9)')}
  ell(c,cx,cy+r*.2,r*.16,r*.11,'#2a1a14');
  c.strokeStyle='#2a1a14';c.lineWidth=Math.max(1,r*.08);c.beginPath();c.moveTo(cx,cy+r*.3);c.lineTo(cx,cy+r*.42);c.moveTo(cx-r*.2,cy+r*.48);c.quadraticCurveTo(cx,cy+r*.56,cx+r*.2,cy+r*.48);c.stroke();
  if(o.blush){ell(c,cx-r*.62,cy+r*.25,r*.14,r*.09,o.blush);ell(c,cx+r*.62,cy+r*.25,r*.14,r*.09,o.blush)}}
function dogBlink(c,cx,cy,r,fur){const ey=cy-r*.12,ex=r*.4;for(const s of [-1,1]){ell(c,cx+s*ex,ey,r*.19,r*.22,fur);c.strokeStyle='#2a1a14';c.lineWidth=Math.max(1.1,r*.1);c.lineCap='round';c.beginPath();c.arc(cx+s*ex,ey-r*.03,r*.16,.15*Math.PI,.85*Math.PI);c.stroke()}}
function tongue(c,cx,cy,r,len){c.fillStyle='#ff6f8e';c.beginPath();c.ellipse(cx,cy+r*.62+len*.5,r*.16,r*.14+len*.5,0,0,TAU);c.fill()}

